using System;using System.IO;using System.Linq;using System.Threading.Tasks;using UnityEngine;using UnityEditor;using UnityEngine.Rendering;using UnityEngine.Rendering.Universal;using RoadGunner;using RoadGunner.Editor;
public static class ConceptCapture {
 static async Task Wait(float n){float end=Time.realtimeSinceStartup+n;while(Time.realtimeSinceStartup<end)await Task.Delay(25);}
 public static async Task<string> Main(string mode,string label){if(!EditorApplication.isPlaying)throw new Exception("Enter Play first");Application.runInBackground=true;var s=UnityEngine.Object.FindAnyObjectByType<GameSession>();s.Restart();s.spawns.enabled=false;s.turret.enabled=false;s.health.DamageEnabled=false;foreach(var r in s.spawns.authoredRaiders){r.enabled=false;if(r.agent.enabled&&r.agent.isOnNavMesh)r.agent.isStopped=true;}s.input.testInput=true;s.input.testBrake=true;s.input.testDirection=Vector2.zero;var axis=Quaternion.Euler(0,45,0);Vector2 p=mode.StartsWith("workshop")?new Vector2(12,-13.2f):mode=="landmark"?new Vector2(-4.5f,-33.2f):mode=="road"?new Vector2(0,-34):mode=="arena"?new Vector2(-33,35):mode=="camp"?new Vector2(27.5f,27):mode=="raiders"?new Vector2(-22,-16):mode=="salvage"?new Vector2(-19,52):new Vector2(0,-47);s.vehicle.ResetPose(axis*new Vector3(p.x*2.5f,.7f,p.y*2.5f),axis*Quaternion.Euler(0,mode=="road"?-30:mode=="arena"?-35:mode.StartsWith("workshop")?20:0,0));s.vehicle.Body.constraints=RigidbodyConstraints.None;await Wait(.6f);s.vehicle.Body.constraints=RigidbodyConstraints.FreezeAll;s.follow.Snap();if(mode.StartsWith("workshop")){s.health.DamageEnabled=true;s.health.Damage(55,false);}await Wait(.3f);Vector3 actorTarget=s.vehicle.transform.position; if(mode=="actors"){foreach(var r in s.spawns.pool)r.Despawn();int i=0;foreach(string name in new[]{"Scavenger","Enforcer","Veteran"}){var r=s.spawns.pool.First(x=>x.visual.name.Contains(name));r.Spawn(s.vehicle.transform.position+axis*new Vector3((i-1)*2.1f,-s.vehicle.transform.position.y,20),-1,0);r.enabled=false;r.agent.isStopped=true;r.transform.rotation=axis;actorTarget=s.vehicle.transform.position+axis*new Vector3(0,-s.vehicle.transform.position.y,20)+Vector3.up*.9f;i++;}}if(mode=="buggy"){var b=s.spawns.buggyPool[0];b.Spawn(s.vehicle.transform.position+axis*new Vector3(0,-s.vehicle.transform.position.y,20),axis,-1);b.AIEnabled=false;b.gun.CanShoot=false;await Wait(.6f);b.Body.constraints=RigidbodyConstraints.FreezeAll;actorTarget=b.transform.position+Vector3.up*.5f;}if(mode=="pickup"){var at=s.vehicle.transform.position+axis*new Vector3(12,0,0);s.pickups.Drop(at,2);s.pickups.DropGear(at+axis*Vector3.right,Vector3.zero);await Wait(.7f);actorTarget=at;}var src=s.follow.GetComponent<Camera>();var go=new GameObject("Temporary art QA capture");var cam=go.AddComponent<Camera>();cam.CopyFrom(src);cam.transform.SetPositionAndRotation(src.transform.position,src.transform.rotation);cam.enabled=false;cam.aspect=720f/1280;var data=cam.GetUniversalAdditionalCameraData();data.renderPostProcessing=src.GetUniversalAdditionalCameraData().renderPostProcessing;data.renderShadows=true;bool close=mode=="close"||mode=="front";if(close){var target=s.vehicle.transform.position+Vector3.up*.75f;var rotation=Quaternion.Euler(32,mode=="front"?195:25,0);cam.orthographic=true;cam.orthographicSize=4.5f;cam.transform.SetPositionAndRotation(target-rotation*Vector3.forward*30,rotation);}bool wide=mode=="workshop-wide";int width=wide?1440:720,height=wide?960:1280;if(wide){var target=UnityEngine.Object.FindAnyObjectByType<RepairWorkshop>().transform.position+Vector3.up;var rotation=Quaternion.Euler(35,20,0);cam.orthographic=true;cam.orthographicSize=12;cam.aspect=width/(float)height;cam.transform.SetPositionAndRotation(target-rotation*Vector3.forward*35,rotation);}if(mode=="actors"||mode=="buggy"||mode=="pickup"){var rotation=Quaternion.Euler(28,200,0);cam.orthographic=true;cam.orthographicSize=mode=="actors"?5:mode=="pickup"?1.8f:4;cam.transform.SetPositionAndRotation(actorTarget-rotation*Vector3.forward*30,rotation);close=true;}var rt=new RenderTexture(width,height,24);rt.antiAliasing=2;rt.Create();cam.targetTexture=rt;var canvas=s.hud.GetComponentInParent<Canvas>();var oldMode=canvas.renderMode;var oldCamera=canvas.worldCamera;float plane=canvas.planeDistance;bool oldEnabled=canvas.enabled;var active=RenderTexture.active;try{if(close||wide)canvas.enabled=false;else{canvas.renderMode=RenderMode.ScreenSpaceCamera;canvas.worldCamera=cam;canvas.planeDistance=1;}await Wait(.1f);Canvas.ForceUpdateCanvases();RenderPipeline.SubmitRenderRequest(cam,new UniversalRenderPipeline.SingleCameraRequest{destination=rt});RenderTexture.active=rt;var texture=new Texture2D(width,height,TextureFormat.RGB24,false);texture.ReadPixels(new Rect(0,0,width,height),0,0);texture.Apply();string folder="/Users/arthuri/Documents/Codex/2026-10-09/macbook-app-store/outputs/concept-overhaul-2026-10-16";Directory.CreateDirectory(folder);string path=folder+"/"+label+"-"+mode+".png";File.WriteAllBytes(path,texture.EncodeToPNG());UnityEngine.Object.Destroy(texture);return path;}finally{canvas.renderMode=oldMode;canvas.worldCamera=oldCamera;canvas.planeDistance=plane;canvas.enabled=oldEnabled;RenderTexture.active=active;rt.Release();UnityEngine.Object.Destroy(rt);UnityEngine.Object.Destroy(go);Canvas.ForceUpdateCanvases();}}
